const getSettings = `-- name: GetSettings :many


SELECT key, value FROM core.settings WHERE key = ANY ($1::text[])
`

type GetSettingsRow struct {
	Key   string
	Value []byte
}

// Phân hệ Lương & Phạt: kỳ lương, phiếu lương, biên bản vi phạm, đơn giá giáo viên, mốc hoa hồng, sổ hoa hồng.
// Đọc trực tiếp bảng của phân hệ đã gộp (iam, crm.leads, finance.receipts / tuitions, academic.*, hr.kpi_*, ops.work_tasks).
// ───────────── Tham số ─────────────
func (q *Queries) GetSettings(ctx context.Context, keys []string) ([]GetSettingsRow, error) {
	rows, err := q.db.Query(ctx, getSettings, keys)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []GetSettingsRow
	for rows.Next() {
		var i GetSettingsRow
		if err := rows.Scan(&i.Key, &i.Value); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

