const upsertSetting = `-- name: UpsertSetting :exec
INSERT INTO core.settings (key, value, description, updated_by) VALUES ($1, $2, $3, $4)
ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, description = coalesce(EXCLUDED.description, core.settings.description),
    updated_by = EXCLUDED.updated_by, updated_at = now()
`

type UpsertSettingParams struct {
	Key         string
	Value       []byte
	Description *string
	UpdatedBy   *uuid.UUID
}

func (q *Queries) UpsertSetting(ctx context.Context, arg UpsertSettingParams) error {
	_, err := q.db.Exec(ctx, upsertSetting,
		arg.Key,
		arg.Value,
		arg.Description,
		arg.UpdatedBy,
	)
	return err
}

const userBranchIDs = `-- name: UserBranchIDs :many
SELECT user_id, branch_id FROM iam.user_branches WHERE user_id = ANY ($1::uuid[])
`

type UserBranchIDsRow struct {
	UserID   uuid.UUID
	BranchID uuid.UUID
}

func (q *Queries) UserBranchIDs(ctx context.Context, ids []uuid.UUID) ([]UserBranchIDsRow, error) {
	rows, err := q.db.Query(ctx, userBranchIDs, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []UserBranchIDsRow
	for rows.Next() {
		var i UserBranchIDsRow
		if err := rows.Scan(&i.UserID, &i.BranchID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const userFullName = `-- name: UserFullName :one
SELECT full_name FROM iam.users WHERE id = $1
`

func (q *Queries) UserFullName(ctx context.Context, id uuid.UUID) (string, error) {
	row := q.db.QueryRow(ctx, userFullName, id)
	var full_name string
	err := row.Scan(&full_name)
	return full_name, err
}

const usersBrief = `-- name: UsersBrief :many
SELECT u.id, u.full_name, coalesce(u.code::text, '')::text AS code, coalesce(u.email::text, '')::text AS email,
    coalesce((SELECT array_agg(ur.role ORDER BY ur.role) FROM iam.user_roles ur WHERE ur.user_id = u.id), '{}')::text[] AS roles,
    coalesce((SELECT b.name FROM iam.user_branches ub JOIN core.branches b ON b.id = ub.branch_id
     WHERE ub.user_id = u.id ORDER BY ub.is_primary DESC, b.name LIMIT 1), '')::text AS branch_name
FROM iam.users u WHERE u.id = ANY ($1::uuid[])
`

type UsersBriefRow struct {
	ID         uuid.UUID
	FullName   string
	Code       string
	Email      string
	Roles      []string
	BranchName string
}

func (q *Queries) UsersBrief(ctx context.Context, ids []uuid.UUID) ([]UsersBriefRow, error) {
	rows, err := q.db.Query(ctx, usersBrief, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []UsersBriefRow
	for rows.Next() {
		var i UsersBriefRow
		if err := rows.Scan(
			&i.ID,
			&i.FullName,
			&i.Code,
			&i.Email,
			&i.Roles,
			&i.BranchName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const violationCountsByUser = `-- name: ViolationCountsByUser :many
SELECT user_id, count(*)::int AS n FROM hr.penalties
WHERE user_id = ANY ($1::uuid[]) AND status <> 'cancelled' AND violation_date BETWEEN $2 AND $3
GROUP BY user_id
`

type ViolationCountsByUserParams struct {
	UserIds []uuid.UUID
	FromDay time.Time
	ToDay   time.Time
}

type ViolationCountsByUserRow struct {
	UserID uuid.UUID
	N      int32
}

// Số biên bản chưa hủy có ngày vi phạm trong khoảng của từng người.
func (q *Queries) ViolationCountsByUser(ctx context.Context, arg ViolationCountsByUserParams) ([]ViolationCountsByUserRow, error) {
	rows, err := q.db.Query(ctx, violationCountsByUser, arg.UserIds, arg.FromDay, arg.ToDay)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ViolationCountsByUserRow
	for rows.Next() {
		var i ViolationCountsByUserRow
		if err := rows.Scan(&i.UserID, &i.N); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const voidCancelledReceiptItems = `-- name: VoidCancelledReceiptItems :exec
UPDATE hr.commission_items i SET status = 'void', deferred_reason = 'Phiếu thu đã bị hủy / không còn duyệt', updated_at = now()
FROM finance.receipts r
WHERE r.id = i.receipt_id AND r.status <> 'approved' AND i.settled_at IS NULL AND i.status <> 'void'
  AND i.payroll_record_id IS NULL AND i.earned_period_end < $1
`

// Khoản hoãn từ kỳ trước mà phiếu đã bị hủy / không còn duyệt → hủy.
func (q *Queries) VoidCancelledReceiptItems(ctx context.Context, startDay time.Time) error {
	_, err := q.db.Exec(ctx, voidCancelledReceiptItems, startDay)
	return err
}

const voidItem = `-- name: VoidItem :exec
UPDATE hr.commission_items SET status = 'void', payroll_record_id = NULL, deferred_reason = $1, updated_at = now() WHERE id = $2
`

type VoidItemParams struct {
	Reason *string
	ID     uuid.UUID
}

func (q *Queries) VoidItem(ctx context.Context, arg VoidItemParams) error {
	_, err := q.db.Exec(ctx, voidItem, arg.Reason, arg.ID)
	return err
}

const voidStaleItems = `-- name: VoidStaleItems :exec
UPDATE hr.commission_items i SET status = 'void', payroll_record_id = NULL,
    deferred_reason = 'Phiếu thu không còn là căn cứ hoa hồng', updated_at = now()
WHERE i.settled_at IS NULL AND i.status <> 'void' AND i.earned_period_start = $1
  AND NOT (i.receipt_id = ANY ($2::uuid[]))
  AND NOT EXISTS (SELECT 1 FROM hr.payroll_records r JOIN hr.payroll_periods p ON p.id = r.period_id
                  WHERE r.id = i.payroll_record_id AND p.status IN ('approved', 'paid'))
`

type VoidStaleItemsParams struct {
	StartDay time.Time
	Keep     []uuid.UUID
}

// Phiếu phát sinh trong kỳ nhưng không còn là căn cứ → hủy khoản chưa trả (khoản đã trả không sửa).
func (q *Queries) VoidStaleItems(ctx context.Context, arg VoidStaleItemsParams) error {
	_, err := q.db.Exec(ctx, voidStaleItems, arg.StartDay, arg.Keep)
	return err
}
